/*
 * onnx2c_memmap.h
 * ----------------
 * User-editable memory placement for this folder's onnx2c (DEEPCRAFT /
 * Viper Studio) TriCore export.
 *
 * model_onnx2c.c includes this file automatically when the TriCore build
 * defines ONNX2C_MEMMAP (see the ".cproject" -> "Defined symbols (-D)" list
 * for the "AURIX GCC Compiler" tool; it's on by default). Because this file
 * is hand-maintained (not generated by onnx2c), it survives regenerating
 * model.c / model_onnx2c.c from a new model export.
 *
 * It overrides the two placement macros the generated code applies to every
 * static tensor it declares:
 *
 *   ATTR_RW_DEFAULT - the onnx2c "tuN" read/write scratch buffers used to
 *                      pass intermediate results between inference nodes.
 *                      Uninitialized at load time -> must land in a
 *                      bss-like (zero-init, no flash image) section.
 *   ATTR_RO_DEFAULT - the read-only weight/constant tensors baked into the
 *                      model. Initialized at load time -> either copied
 *                      from flash into RAM at startup (data-like section),
 *                      or left directly in flash and read in place (XIP,
 *                      zero RAM cost).
 *
 * This project's linker script (Lcf_Gcc_Tricore_Tc.lsl) gives CPU0 two RAM
 * regions to place these in:
 *   - DSPR0 : CPU0's private data scratchpad, 240 KB total. Also holds the
 *             app stack/heap/CSA plus the streaming stack's lwIP/FreeRTOS
 *             pools, so it fills up fast once a model grows.
 *   - LMU   : CPU0's on-chip Local Memory Unit, 512 KB total, otherwise
 *             unused by this firmware. Selected below as the default.
 *
 * See the "Configuration reference" section of the top-level README.md for
 * the full DSPR0-vs-LMU tradeoff and how to change these.
 */
#ifndef ONNX2C_MEMMAP_H
#define ONNX2C_MEMMAP_H

#define ONNX2C_MEM_DSPR0 1   /* CPU0 data scratchpad, 240 KB total, shared with stack/heap/lwIP/FreeRTOS */
#define ONNX2C_MEM_LMU   2   /* CPU0 Local Memory Unit, 512 KB total, otherwise unused by this firmware  */
#define ONNX2C_MEM_FLASH 3   /* Program flash, read/executed in place (XIP) -- read-only tensors only    */

/* ---------------------------------------------------------------------
 * Read/write scratch tensors (onnx2c's tuN double-buffers). FLASH is not a
 * valid choice here (they are written to at runtime).
 * --------------------------------------------------------------------- */
#ifndef ONNX2C_RW_PLACEMENT
#define ONNX2C_RW_PLACEMENT ONNX2C_MEM_LMU   /* change to ONNX2C_MEM_DSPR0 to go back to plain .bss */
#endif

#if ONNX2C_RW_PLACEMENT == ONNX2C_MEM_LMU
#define ATTR_RW_DEFAULT __attribute__((section(".lmubss_cpu0")))
#elif ONNX2C_RW_PLACEMENT == ONNX2C_MEM_DSPR0
#define ATTR_RW_DEFAULT /* plain -> .bss -> DSPR0 (dsram0) */
#else
#error "onnx2c_memmap.h: ONNX2C_RW_PLACEMENT must be ONNX2C_MEM_LMU or ONNX2C_MEM_DSPR0"
#endif

/* ---------------------------------------------------------------------
 * Read-only weight/constant tensors. FLASH keeps them out of RAM entirely
 * (TriCore program flash is memory-mapped and directly readable by the CPU,
 * no copy needed); DSPR0/LMU copy them into RAM at startup instead, which
 * can be faster to access repeatedly than flash but costs RAM. If a model's
 * weights are large enough to threaten the 512 KB LMU budget (shared with
 * the RW scratch buffers above), switch this to ONNX2C_MEM_FLASH.
 * --------------------------------------------------------------------- */
#ifndef ONNX2C_RO_PLACEMENT
#define ONNX2C_RO_PLACEMENT ONNX2C_MEM_LMU   /* change to ONNX2C_MEM_DSPR0 or ONNX2C_MEM_FLASH */
#endif

#if ONNX2C_RO_PLACEMENT == ONNX2C_MEM_LMU
#define ATTR_RO_DEFAULT __attribute__((section(".lmudata_cpu0")))
#elif ONNX2C_RO_PLACEMENT == ONNX2C_MEM_DSPR0
#define ATTR_RO_DEFAULT __attribute__((section(".data_cpu0")))
#elif ONNX2C_RO_PLACEMENT == ONNX2C_MEM_FLASH
#define ATTR_RO_DEFAULT /* plain const -> .rodata -> flash, XIP, 0 bytes of RAM */
#else
#error "onnx2c_memmap.h: ONNX2C_RO_PLACEMENT must be ONNX2C_MEM_LMU, ONNX2C_MEM_DSPR0 or ONNX2C_MEM_FLASH"
#endif
#endif /* ONNX2C_MEMMAP_H */
